// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleOrders) predicate.BundleOrders {
	return predicate.BundleOrders(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleOrders) predicate.BundleOrders {
	return predicate.BundleOrders(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleOrders) predicate.BundleOrders {
	return predicate.BundleOrders(sql.NotPredicates(p))
}
